cypress_script:
describe('Floating Navigation Menu Links', () => {
  it('should navigate to Home section', () => {
    cy.visit('https://the-internet.herokuapp.com/floating_menu');
    cy.get('a').contains('Home').click();
    cy.url().should('include', '#home');
  });

  it('should remain on the same page when an invalid link is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/floating_menu');
    cy.get('a').contains('About').click();
    cy.url().should('include', '#about');
    cy.get('#menu').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Floating Navigation Menu Links', () => {
  test('should navigate to Home section', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/floating_menu');
    await page.click('a:text("Home")');
    await expect(page).toHaveURL(/.*#home/);
  });

  test('should remain on the same page when an invalid link is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/floating_menu');
    await page.click('a:text("About")');
    await expect(page).toHaveURL(/.*#about/);
    await expect(page.locator('#menu')).toBeVisible();
  });
});
